{
  "actions": [
    {
      "action": "Replace completeness with component-level evidence",
      "mechanism": "Record presence separately from condition so counting cannot imply verified good condition.",
      "implementation": "Create ten ID rows with presence, condition category, inspector, and timestamp. Default condition to unknown; remove the editable complete checkbox.",
      "check": "Return ten counted, uninspected components: display ten present, ten condition unknown, and zero verified good.",
      "risk": "Bulk entry could fabricate evidence; prohibit bulk verified-good updates."
    },
    {
      "action": "Require an explicit shift-transfer receipt",
      "mechanism": "Separate custody acceptance from inspection approval, preserving responsibility without inventing evidence.",
      "implementation": "Show the kit, unresolved IDs, and current custodian. Incoming staff acknowledge custody; record both staff identities and transfer time without changing conditions.",
      "check": "Transfer a counted-only return: the incoming custodian changes, while all ten conditions remain unknown and earlier records remain visible.",
      "risk": "Unaccepted transfers need a named on-duty supervisor as escalation owner."
    },
    {
      "action": "Assign every missing component a recovery task",
      "mechanism": "Turn absence into owned work rather than an unresolved warning.",
      "implementation": "For each missing ID, require a named staff owner, next action, and due time. Offer actions such as checking the return station or contacting the borrower.",
      "check": "Mark one ID missing; verify its task survives shift transfer and cannot close without a recorded outcome.",
      "risk": "Task ownership must not imply borrower fault or automatic charges."
    },
    {
      "action": "Timebox handoff and defer unfinished inspection explicitly",
      "mechanism": "Protect the three-minute limit by transferring unresolved work instead of rushing verification.",
      "implementation": "At two minutes, stop new inspection work and summarize remaining unknown IDs. By three minutes, assign follow-up ownership and acknowledge custody.",
      "check": "Run a timed handoff with all ten conditions unknown; finish within 180 seconds with every unresolved ID assigned.",
      "risk": "Deferred inspection can accumulate; escalate overdue work to the shift supervisor."
    },
    {
      "action": "Separate custody received from ready to lend",
      "mechanism": "Allow incomplete returns to be accepted without presenting them as cleared equipment.",
      "implementation": "Use separate custody and readiness labels. Keep readiness pending while any component is missing or unknown; apply documented lending rules to verified condition categories.",
      "check": "Accept a counted-only return: custody shows received, readiness stays pending, and the normal checkout path remains unavailable.",
      "risk": "Pending kits reduce availability; display the blocking IDs and follow-up owner."
    },
    {
      "action": "Provide a kit-bound paper continuity record",
      "mechanism": "Carry evidence through workstation outages without photographs, personal devices, or tracking hardware.",
      "implementation": "Keep a numbered ten-ID form with the kit, including presence, condition, inspector, time, custody acceptance, and exception ownership. Reconcile it into the ledger afterward.",
      "check": "Simulate an outage and shift change; incoming staff identify unknown conditions and missing-item owners from the form within three minutes.",
      "risk": "Conflicting copies require one designated original and documented reconciliation."
    },
    {
      "action": "Prevent old inspections from clearing new returns",
      "mechanism": "Scope evidence to each lending cycle so historical good condition cannot become current verification.",
      "implementation": "Open a new return record with every presence and condition field unknown. Retain prior inspections as labeled history; require fresh evidence for current verification.",
      "check": "Return a previously verified-good kit and record only its count: current conditions remain unknown while prior results remain accessible.",
      "risk": "Cycle creation errors require correction history rather than silent overwriting."
    }
  ],
  "abstention_reason": ""
}
